#include "support/process.hpp"
using namespace test;
int main(int argc,char** argv){try{check(argc==2,"nano required");std::string binary=argv[1],receiver="0x00000000000000000000000000000000000000ab";Temp root;Env env={{"NANO_WALLET_PASSWORD","fixture-password"},{"NANO_PRIVATE_KEY",key()}};auto genesis=root/"genesis.json",wallet=root/"wallet.json",config=root/"dev.json";save(genesis,{{"config",{{"chainId",1337},{"consensus","pos"}}},{"alloc",{{account,{{"balance",quantity(Int("100000000000000000000000"))}}}}}});success(run({binary,"wallet","import",wallet.string()},env));save(config,{{"dev_mode",true}});
 Process server({binary,"serve",genesis.string(),(root/"db").string(),"0","127.0.0.1",config.string()});int port=server.port();auto cli=[&](std::vector<std::string> args){args.insert(args.begin(),{binary,"rpc",url(port)});auto r=run(args,env);check(r.out.find(key())==std::string::npos&&r.out.find("fixture-password")==std::string::npos,"secret exposed");return success(r);};auto produce=[&]{auto selected=rpc(port,"validator_isSelected",{account})["selectedValidator"];check(rpc(port,"validator_submitBlock",{rpc(port,"validator_getBlockTemplate",{selected})})["success"],"produce");};
 check(cli({"info"})["chainId"]=="0x539"&&cli({"nodes"})["totalPeers"]==0&&cli({"network"})["network"]["name"]=="Nano","query CLI");check(cli({"balance",account})["wei"]=="100000000000000000000000","initial balance");auto first=cli({"send",wallet.string(),receiver,"0.000000000000000001"}),second=cli({"send",wallet.string(),receiver,"1.000000000000000001"});check(first["nonce"]=="0x0"&&second["nonce"]=="0x1"&&cli({"receipt",first["hash"]}).is_null(),"pending nonce and receipt");produce();check(cli({"balance",receiver})["wei"]=="1000000000000000002"&&cli({"receipt",first["hash"]})["status"]=="0x1","exact transfer amounts");
 auto bytecode=root/"contract.hex";{std::ofstream f(bytecode);f<<"0x600a600c600039600a6000f3602a60005260206000f3\n";}
 Process deploy({binary,"rpc",url(port),"deploy",wallet.string(),bytecode.string(),"20"},env);auto submitted=deploy.event("submitted");produce();auto result=deploy.wait(25);check(result.code==0,result.err);auto deployed=Json::parse(result.out.substr(result.out.find('\n')+1));auto contract=deployed["contractAddress"];check(rpc(port,"eth_getCode",{contract,"latest"})=="0x602a60005260206000f3"&&rpc(port,"eth_call",{Json{{"to",contract}},"latest"})=="0x"+std::string(62,'0')+"2a"&&deployed["hash"]==submitted["hash"],"contract execution");
 auto snapshot=rpc(port,"evm_snapshot"),height=rpc(port,"eth_blockNumber");Int timestamp=quantity(rpc(port,"eth_getBlockByNumber",{"latest",false})["timestamp"])+120;rpc(port,"evm_setNextBlockTimestamp",{u64(timestamp)});auto mined=cli({"mine"});check(run({binary,"rpc",url(port),"mine","extra"}).code!=0,"extra mining arg accepted");check(rpc(port,"eth_blockNumber")==quantity(Int(quantity(height)+1))&&quantity(rpc(port,"eth_getBlockByHash",{mined,false})["timestamp"])==timestamp,"dev mining timestamp");check(rpc(port,"evm_revert",{snapshot})==true&&rpc(port,"eth_blockNumber")==height&&rpc(port,"eth_getBlockByHash",{mined,false}).is_null(),"snapshot revert");
 Process normal({binary,"serve",genesis.string(),(root/"normal").string(),"0","127.0.0.1"});int other=normal.port();auto refused=run({binary,"rpc",url(other),"mine"});check(refused.code!=0&&refused.err.find("Development mode is disabled")!=std::string::npos,"production mining RPC enabled");check(success(run({binary,"rpc",url(other),"info"}))["blockNumber"]=="0x0","production node mutated");std::cout<<"Native RPC CLI scenarios passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
